		<style type="text/css" id="wp-custom-css">
			
/* ══════════════════════════════════════
   COLOR PALETTE — extracted from logo
   Primary Green  : #1B6B3A
   Light Green    : #2D9B57
   Gold / Accent  : #C8963E
   Dark Gold      : #A67830
   Off-White      : #F9F6EF
   Dark           : #121212
══════════════════════════════════════ */

*, *::before, *::after { margin:0; padding:0; box-sizing:border-box; }

:root {
  --green:    #1B6B3A;
  --green-lt: #2D9B57;
  --gold:     #C8963E;
  --gold-dk:  #A67830;
  --cream:    #F9F6EF;
  --dark:     #121212;
  --white:    #ffffff;
}

html { font-size: 16px; scroll-behavior: smooth; }
body { font-family: 'Poppins', sans-serif; background: #eee; }
a    { text-decoration: none; color: inherit; }

/* ─────────────────────────────────────
   1. TICKER
───────────────────────────────────── */
.ticker-bar {
  background: var(--dark);
  height: 42px;
  display: flex;
  align-items: center;
  overflow: hidden;
  border-bottom: 3px solid var(--gold);
  position: relative;
  z-index: 200;
}

.ticker-badge {
  background: var(--gold);
  min-width: 46px;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 18px;
  flex-shrink: 0;
}

.ticker-viewport {
  overflow: hidden;
  flex: 1;
  height: 100%;
  display: flex;
  align-items: center;
  -webkit-mask-image: linear-gradient(to right, transparent, black 30px, black calc(100% - 30px), transparent);
  mask-image: linear-gradient(to right, transparent, black 30px, black calc(100% - 30px), transparent);
}

.ticker-track {
  display: flex;
  white-space: nowrap;
  animation: runTicker 38s linear infinite;
}

.ticker-track span {
  color: var(--gold);
  font-size: 13px;
  font-weight: 500;
  padding-right: 60px;
  letter-spacing: 0.3px;
}

.ticker-track span::before { content: "• "; }

@keyframes runTicker {
  0%   { transform: translateX(0); }
  100% { transform: translateX(-50%); }
}

/* ─────────────────────────────────────
   2. LOGO ZONE
───────────────────────────────────── */
.logo-zone {
  background: var(--green);
  padding: 20px 20px 16px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  background-image:
    radial-gradient(circle at 20% 50%, rgba(255,255,255,0.04) 0%, transparent 60%),
    radial-gradient(circle at 80% 50%, rgba(200,150,62,0.08) 0%, transparent 60%);
}

.logo-ring {
  width: 110px;
  height: 110px;
  border-radius: 50%;
  border: 3px solid var(--gold);
  box-shadow:
    0 0 0 5px rgba(200,150,62,0.18),
    0 8px 24px rgba(0,0,0,0.30);
  overflow: hidden;
  background: var(--white);
  transition: transform 0.3s, box-shadow 0.3s;
  display: flex;
  align-items: center;
  justify-content: center;
}

.logo-ring:hover {
  transform: scale(1.05);
  box-shadow: 0 0 0 7px rgba(200,150,62,0.30), 0 10px 30px rgba(0,0,0,0.35);
}

.logo-ring img {
  width: 90%;
  height: 90%;
  object-fit: contain;
}

.logo-tagline {
  color: var(--gold);
  font-family: 'Amiri', serif;
  font-size: 13px;
  letter-spacing: 2px;
  text-transform: uppercase;
  opacity: 0.9;
}

/* ─────────────────────────────────────
   3. STICKY NAV BAR
───────────────────────────────────── */
.nav-bar {
  background: var(--white);
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 20px;
  height: 60px;
  box-shadow: 0 3px 18px rgba(27,107,58,0.14);
  position: sticky;
  top: 0;
  z-index: 300;
  border-bottom: 3px solid var(--green);
}

/* Hamburger */
.hamburger {
  display: flex;
  flex-direction: column;
  gap: 5px;
  cursor: pointer;
  padding: 8px;
  border-radius: 6px;
  border: none;
  background: transparent;
  transition: background 0.2s;
}
.hamburger:hover { background: #f0f7f3; }
.hamburger span {
  display: block;
  width: 24px;
  height: 2.5px;
  background: var(--green);
  border-radius: 3px;
  transition: all 0.3s ease;
}
.hamburger.active span:nth-child(1) { transform: translateY(7.5px) rotate(45deg); }
.hamburger.active span:nth-child(2) { opacity: 0; transform: scaleX(0); }
.hamburger.active span:nth-child(3) { transform: translateY(-7.5px) rotate(-45deg); }

/* Desktop nav links */
.nav-links {
  display: none;
  gap: 2px;
  align-items: center;
  list-style: none;
}
.nav-links a {
  font-size: 13.5px;
  font-weight: 500;
  color: var(--dark);
  padding: 8px 14px;
  border-radius: 6px;
  transition: background 0.2s, color 0.2s;
  white-space: nowrap;
}
.nav-links a:hover { background: var(--green); color: var(--white); }

/* Right side */
.nav-right {
  display: flex;
  align-items: center;
  gap: 8px;
}

/* Social icons */
.social-strip { display: flex; gap: 7px; align-items: center; }

.s-icon {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: var(--green);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: background 0.25s, transform 0.25s;
  cursor: pointer;
  flex-shrink: 0;
}
.s-icon:hover { background: var(--gold); transform: scale(1.13) rotate(-6deg); }
.s-icon svg { width: 16px; height: 16px; fill: var(--white); }

/* Donate pill (desktop) */
.donate-pill {
  display: none;
  background: var(--gold);
  color: var(--white);
  font-weight: 700;
  font-size: 13px;
  padding: 9px 22px;
  border-radius: 30px;
  white-space: nowrap;
  transition: background 0.2s, transform 0.2s;
  margin-left: 4px;
  letter-spacing: 0.3px;
}
.donate-pill:hover { background: var(--gold-dk); transform: translateY(-1px); }

/* ─────────────────────────────────────
   4. MOBILE DROPDOWN
───────────────────────────────────── */
.mobile-nav {
  background: var(--white);
  max-height: 0;
  overflow: hidden;
