    <style>
    /* ═══════════════════════════════════════════
       AL-MIFTAH CUSTOM HEADER STYLES
       Colors from logo:
         Green  : #1B6B3A
         Gold   : #C8963E
    ═══════════════════════════════════════════ */

    /* ── 1. TICKER BAR ── */
    .almiftah-ticker-bar {
        background: #121212;
        height: 42px;
        display: flex;
        align-items: center;
        overflow: hidden;
        border-bottom: 3px solid #C8963E;
        position: relative;
        z-index: 9999;
        width: 100%;
    }
    .almiftah-ticker-badge {
        background: #C8963E;
        min-width: 46px;
        height: 100%;
        display: flex;
        align-items: center;
        justify-content: center;
        font-size: 18px;
        flex-shrink: 0;
    }
    .almiftah-ticker-viewport {
        overflow: hidden;
        flex: 1;
        height: 100%;
        display: flex;
        align-items: center;
        -webkit-mask-image: linear-gradient(to right, transparent, black 30px, black calc(100% - 30px), transparent);
        mask-image: linear-gradient(to right, transparent, black 30px, black calc(100% - 30px), transparent);
    }
    .almiftah-ticker-track {
        display: flex;
        white-space: nowrap;
        animation: almiftahTicker 38s linear infinite;
    }
    .almiftah-ticker-track span {
        color: #C8963E;
        font-size: 13px;
        font-weight: 500;
        padding-right: 60px;
        font-family: 'Poppins', sans-serif;
        letter-spacing: 0.3px;
    }
    .almiftah-ticker-track span::before {
        content: "• ";
    }
    @keyframes almiftahTicker {
        0%   { transform: translateX(0); }
        100% { transform: translateX(-50%); }
    }

    /* ── 2. LOGO ZONE ── */
    .almiftah-logo-zone {
        background: #1B6B3A;
        padding: 18px 20px 14px;
        display: flex;
        flex-direction: column;
        align-items: center;
        justify-content: center;
        gap: 8px;
        background-image:
            radial-gradient(circle at 20% 50%, rgba(255,255,255,0.04) 0%, transparent 60%),
            radial-gradient(circle at 80% 50%, rgba(200,150,62,0.08) 0%, transparent 60%);
        width: 100%;
    }
    .almiftah-logo-ring {
        width: 110px;
        height: 110px;
        border-radius: 50%;
        border: 3px solid #C8963E;
        box-shadow: 0 0 0 5px rgba(200,150,62,0.18), 0 8px 24px rgba(0,0,0,0.30);
        overflow: hidden;
        background: #fff;
        display: flex;
        align-items: center;
        justify-content: center;
        transition: transform 0.3s, box-shadow 0.3s;
        text-decoration: none;
    }
    .almiftah-logo-ring:hover {
        transform: scale(1.05);
        box-shadow: 0 0 0 7px rgba(200,150,62,0.30), 0 10px 30px rgba(0,0,0,0.35);
    }
    .almiftah-logo-ring img {
        width: 90%;
        height: 90%;
        object-fit: contain;
    }
    .almiftah-logo-tagline {
        color: #C8963E;
        font-family: 'Amiri', serif;
        font-size: 13px;
        letter-spacing: 2px;
        text-transform: uppercase;
        opacity: 0.9;
        text-align: center;
    }

    /* ── 3. NAV BAR ── */
    .almiftah-nav-bar {
        background: #fff;
        display: flex;
        align-items: center;
        justify-content: space-between;
        padding: 0 20px;
        height: 60px;
        box-shadow: 0 3px 18px rgba(27,107,58,0.14);
        position: sticky;
        top: 0;
        z-index: 9998;
        border-bottom: 3px solid #1B6B3A;
        width: 100%;
        box-sizing: border-box;
    }

    /* Hamburger */
    .almiftah-hamburger {
        display: flex;
        flex-direction: column;
        gap: 5px;
        cursor: pointer;
        padding: 8px;
        border-radius: 6px;
        border: none;
        background: transparent;
        transition: background 0.2s;
    }
    .almiftah-hamburger:hover { background: #f0f7f3; }
    .almiftah-hamburger span {
        display: block;
        width: 24px;
        height: 2.5px;
        background: #1B6B3A;
        border-radius: 3px;
        transition: all 0.3s ease;
    }
    .almiftah-hamburger.active span:nth-child(1) { transform: translateY(7.5px) rotate(45deg); }
    .almiftah-hamburger.active span:nth-child(2) { opacity: 0; transform: scaleX(0); }
    .almiftah-hamburger.active span:nth-child(3) { transform: translateY(-7.5px) rotate(-45deg); }

    /* Desktop nav links */
    .almiftah-nav-links {
        display: none;
        gap: 2px;
        align-items: center;
        list-style: none;
        margin: 0;
        padding: 0;
    }
    .almiftah-nav-links a {
        font-size: 13.5px;
        font-weight: 500;
        color: #121212;
        padding: 8px 14px;
        border-radius: 6px;
        transition: background 0.2s, color 0.2s;
        white-space: nowrap;
        font-family: 'Poppins', sans-serif;
        text-decoration: none;
    }
    .almiftah-nav-links a:hover {
        background: #1B6B3A;
        color: #fff;
    }

    /* Right side */
    .almiftah-nav-right {
        display: flex;
        align-items: center;
        gap: 8px;
    }

    /* Social icons */
    .almiftah-social-strip {
        display: flex;
        gap: 7px;
        align-items: center;
    }
    .almiftah-s-icon {
        width: 36px;
        height: 36px;
        border-radius: 50%;
        background: #1B6B3A;
        display: flex;
        align-items: center;
        justify-content: center;
        transition: background 0.25s, transform 0.25s;
        cursor: pointer;
        flex-shrink: 0;
        text-decoration: none;
    }
    .almiftah-s-icon:hover {
        background: #C8963E;
        transform: scale(1.13) rotate(-6deg);
    }
    .almiftah-s-icon svg {
        width: 16px;
        height: 16px;
        fill: #fff;
    }

    /* Donate pill — desktop only */
    .almiftah-donate-pill {
        display: none;
        background: #C8963E;
        color: #fff;
        font-weight: 700;
        font-size: 13px;
        padding: 9px 22px;
        border-radius: 30px;
        white-space: nowrap;
        transition: background 0.2s, transform 0.2s;
        margin-left: 4px;
        letter-spacing: 0.3px;
        font-family: 'Poppins', sans-serif;
        text-decoration: none;
    }
    .almiftah-donate-pill:hover {
        background: #A67830;
        transform: translateY(-1px);
        color: #fff;
    }

    /* ── 4. MOBILE DROPDOWN ── */
    .almiftah-mobile-nav {
        background: #fff;
        max-height: 0;
        overflow: hidden;
        transition: max-height 0.42s cubic-bezier(0.4, 0, 0.2, 1);
        position: sticky;
        top: 60px;
        z-index: 9997;
        box-shadow: 0 8px 24px rgba(0,0,0,0.08);
        border-left: 4px solid #1B6B3A;
        width: 100%;
    }
    .almiftah-mobile-nav.open { max-height: 520px; }
    .almiftah-mobile-nav a {
        display: flex;
        align-items: center;
        gap: 12px;
        padding: 13px 24px;
        font-size: 14.5px;
        font-weight: 500;
        color: #121212;
        border-bottom: 1px solid #f0f0f0;
        transition: background 0.2s, color 0.2s, padding-left 0.22s;
        font-family: 'Poppins', sans-serif;
        text-decoration: none;
    }
    .almiftah-mobile-nav a:hover {
        background: #f0faf4;
        color: #1B6B3A;
        padding-left: 32px;
    }
    .almiftah-mobile-nav .m-donate {
        background: #C8963E;
        color: #fff !important;
        font-weight: 700;
        justify-content: center;
        margin: 12px 20px 16px;
        border-radius: 8px;
        border-bottom: none !important;
        padding: 13px 24px !important;
        letter-spacing: 0.3px;
    }
    .almiftah-mobile-nav .m-donate:hover {
        background: #A67830;
        padding-left: 24px !important;
    }

    /* ── RESPONSIVE ── */
    @media (min-width: 640px) {
        .almiftah-ticker-bar { height: 44px; }
        .almiftah-ticker-track span { font-size: 14px; }
        .almiftah-logo-zone { padding: 22px 20px 16px; }
        .almiftah-logo-ring { width: 124px; height: 124px; }
        .almiftah-logo-tagline { font-size: 14px; }
        .almiftah-nav-bar { padding: 0 32px; height: 64px; }
    }
    @media (min-width: 1024px) {
        .almiftah-hamburger   { display: none !important; }
